# --- Logging Setup ---
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# --- File Type Definitions ---
VIDEO_EXTS = [
    '.mov', '.mp4', '.m4v', '.mpg', '.mpeg', '.avi', '.mxf'
]
PHOTO_EXTS = [
    '.jpg', '.jpeg', '.png', '.arw', # Sony RAW
    '.cr2', '.cr3', # Canon RAW
    '.nef', '.nrw', # Nikon RAW
    '.raf', # Fuji RAW
    '.dng', # Adobe RAW
    '.heic', '.tif', '.tiff'
]
AUDIO_EXTS = [
    '.wav', '.mp3', '.aiff', '.flac', '.m4a'
]
ALL_MEDIA_EXTS = VIDEO_EXTS + PHOTO_EXTS + AUDIO_EXTS

# ==============================================================================
#  FUNCTION 1: safe_move_file (Copy, Verify, Delete)
# ==============================================================================

def safe_move_file(source_path, dest_path, delete_source=True):
    """
    Safely copies a file, verifies the copy by size, and then
    deletes the source if verification passes and delete_source is True.
    """
    try:
        # --- 1. COPY ---
        logging.debug(f"Copying: {source_path} -> {dest_path}")
        shutil.copy2(source_path, dest_path)

        # --- 2. VERIFY ---
        source_size = os.path.getsize(source_path)
        dest_size = os.path.getsize(dest_path)

        if source_size == dest_size:
            logging.info(f"Verified OK: {os.path.basename(dest_path)}")
            
            # --- 3. DELETE (Optional) ---
            if delete_source:
                try:
                    os.remove(source_path)
                    logging.debug(f"Deleted source: {source_path}")
                except Exception as e:
                    logging.error(f"Failed to delete source {source_path}: {e}")
                    # Don't fail the whole operation, copy was good.
            return True
        else:
            # Verification FAILED!
            logging.error(
                f"VERIFICATION FAILED for {source_path}. "
                f"Sizes mismatch: Source={source_size} vs Dest={dest_size}"
            )
            # Clean up the bad copy
            os.remove(dest_path)
            return False

    except Exception as e:
        logging.error(f"Failed to move {source_path}: {e}")
        # Clean up partial destination file if it exists
        if os.path.exists(dest_path):
            os.remove(dest_path)
        return False

# ==============================================================================
#  FUNCTION 2: find_camera_model (No-Crash EXIF Reader)
# ==============================================================================

def find_camera_model(file_sample_list):
    """
    Tries to find camera Make and Model from a small list of files.
    This function is designed to never crash the import.
    """
    logging.debug(f"Checking {len(file_sample_list)} files for camera model...")
    for file_path in file_sample_list:
        try:
            with open(file_path, 'rb') as f:
                # Stop after finding the model tag for speed
                tags = exifread.process_file(f, stop_tag='Image Model', details=False)

                if 'Image Make' in tags and 'Image Model' in tags:
                    make = str(tags['Image Make']).strip()
                    model = str(tags['Image Model']).strip()
                    
                    if model.lower().startswith(make.lower()):
                        model = model[len(make):].strip() # Slice off the 'make' part
                    
                    # Sanitize JUST the model for the folder name
                    sanitized_model = re.sub(r'[^\w\s-]', '', model)
                    sanitized_model = re.sub(r'[-\s]+', '_', sanitized_model).strip('_')
                    
                    if sanitized_model: # Ensure it's not an empty string
                        logging.info(f"Found camera model: {sanitized_model}")
                        return sanitized_model
        except Exception as e:
            # This is expected for non-EXIF files (e.g., videos)
            logging.warning(f"Could not read EXIF from {file_path}: {e}")
    
    logging.info("No camera model found in sample files.")
    return None

# ==============================================================================
#  FUNCTION 3: create_destination_structure (The Folder Maker)
# ==============================================================================

def create_destination_structure(base_path, camera_model=None):
    """
    Creates the unique, enumerated YYYY-MM-DD folder and all subfolders.
    NOW RETURNS: (paths_map, final_date_folder_path)
    """
    # --- 1. Find unique enumerated folder name ---
    today_str = datetime.date.today().strftime("%Y-%m-%d")
    final_date_folder = os.path.join(base_path, today_str)
    
    counter = 1
    while os.path.exists(final_date_folder):
        counter += 1
        final_date_folder = os.path.join(base_path, f"{today_str}_{counter}")
        
    logging.info(f"Creating new import folder: {final_date_folder}")

    # --- 2. Define all paths ---
    paths = {
        'projects': os.path.join(final_date_folder, '00-Projects'),
        'projects_backups': os.path.join(final_date_folder, '00-Projects', '01-Backups'),
        'projects_documents': os.path.join(final_date_folder, '00-Projects', '02-Documents'),
        'video_footage': os.path.join(final_date_folder, '01-Video', '01-Footage'),
        'video_downloads': os.path.join(final_date_folder, '01-Video', '02-Downloads'),
        'audio_external': os.path.join(final_date_folder, '02-Audio', '01-External Mics'),
        'audio_music': os.path.join(final_date_folder, '02-Audio', '02-Music'),
        'audio_sfx': os.path.join(final_date_folder, '02-Audio', '03-SFX'),
        'image_photos': os.path.join(final_date_folder, '03-Images', '01-Photos'),
        'image_graphics': os.path.join(final_date_folder, '03-Images', '02-Graphics'),
        'trash': os.path.join(final_date_folder, 'TRASH')
    }

    # --- 3. Add camera model if it exists ---
    if camera_model:
        paths['video_footage'] = os.path.join(paths['video_footage'], camera_model)
        paths['image_photos'] = os.path.join(paths['image_photos'], camera_model)

    # --- 4. Create all directories ---
    for path in paths.values():
        try:
            os.makedirs(path, exist_ok=True)
            logging.debug(f"Created directory: {path}")
        except Exception as e:
            logging.error(f"Could not create directory {path}: {e}")
            return None, None # Return None for both

    # --- 5. Return the simple map AND the new folder path ---
    paths_map = {
        'video': paths['video_footage'],
        'photo': paths['image_photos'],
        'audio': paths['audio_external'],
        'trash': paths['trash']
    }
    return paths_map, final_date_folder

# ==============================================================================
#  FUNCTION 4: open_path_in_explorer
# ==============================================================================

def open_path_in_explorer(path):
    """
    Opens the given path in the native file explorer (Finder/File Explorer).
    """
    try:
        if sys.platform == "win32":
            os.startfile(os.path.normpath(path))
        elif sys.platform == "darwin": # macOS
            subprocess.call(["open", path])
        else: # Linux
            subprocess.call(["xdg-open", path])
        logging.info(f"Opening output folder: {path}")
    except Exception as e:
        logging.error(f"Failed to open output folder: {e}")

# ==============================================================================
#  FUNCTION 5: run_import (The Main Engine)
# ==============================================================================

def run_import(source_dir, dest_base, delete_source=True, pause_event=None, progress_callback=None):
    """
    Runs the entire import process from start to finish.
    """
    
    # --- 0. NORMALIZE PATHS ---
    try:
        source_dir = os.path.normpath(source_dir)
        dest_base = os.path.normpath(dest_base)
    except Exception as e:
        logging.error(f"Invalid path provided: {e}")
        if progress_callback: progress_callback(0, f"ERROR: Invalid path")
        return

    def report_progress(current, total, message):
        """Helper to call the progress callback."""
        if progress_callback:
            percent = int((current / total) * 100)
            status = f"{message} ({current}/{total})"
            progress_callback(percent, status)

    # --- 1. SCAN ---
    logging.info(f"Scanning {source_dir} for files...")
    media_files = []
    trash_files = []
    
    for root, dirs, files in os.walk(source_dir):
        for file in files:
            if file.startswith('.'):
                continue
            file_path = os.path.join(root, file)
            ext = os.path.splitext(file)[1].lower()
            if ext in ALL_MEDIA_EXTS:
                media_files.append(file_path)
            else:
                trash_files.append(file_path)

    total_files = len(media_files) + len(trash_files)
    if total_files == 0:
        logging.info("No files found to import.")
        if progress_callback: progress_callback(100, "No files found.")
        return "COMPLETE" 

    logging.info(f"Found {len(media_files)} media files and {len(trash_files)} other files.")

    # --- 2. ANALYZE ---
    sample_list = media_files[:10]
    camera_model = find_camera_model(sample_list)

    # --- 3. PREPARE ---
    paths_map, new_folder_path = create_destination_structure(dest_base, camera_model)
    if paths_map is None:
        logging.error("Failed to create destination structure. Aborting.")
        if progress_callback: progress_callback(0, "ERROR: Could not create folders.")
        return "ERROR" 

    processed_count = 0
    
    # --- 4. PROCESS MEDIA ---
    logging.info(f"Importing {len(media_files)} media files...")
    for file_path in media_files:
        
        if pause_event and pause_event.is_set():
            logging.warning("Pause requested. Stopping import.")
            if progress_callback: report_progress(processed_count, total_files, "Pausing...")
            return "PAUSED" 

        ext = os.path.splitext(file_path)[1].lower()
        dest_folder = None
        
        if ext in VIDEO_EXTS: dest_folder = paths_map['video']
        elif ext in PHOTO_EXTS: dest_folder = paths_map['photo']
        elif ext in AUDIO_EXTS: dest_folder = paths_map['audio']
        
        if dest_folder:
            dest_file_path = os.path.join(dest_folder, os.path.basename(file_path))
            safe_move_file(file_path, dest_file_path, delete_source)
            
        processed_count += 1
        report_progress(processed_count, total_files, "Importing media...")

    # --- 5. PROCESS TRASH ---
    logging.info(f"Moving {len(trash_files)} other files to TRASH...")
    for file_path in trash_files:
        
        if pause_event and pause_event.is_set():
            logging.warning("Pause requested. Stopping import.")
            if progress_callback: report_progress(processed_count, total_files, "Pausing...")
            return "PAUSED" 

        try:
            relative_path = os.path.relpath(file_path, source_dir)
            dest_file_path = os.path.join(paths_map['trash'], relative_path)
            os.makedirs(os.path.dirname(dest_file_path), exist_ok=True)
            safe_move_file(file_path, dest_file_path, delete_source)
        except Exception as e:
            logging.error(f"Failed to move to trash {file_path}: {e}")
            
        processed_count += 1
        report_progress(processed_count, total_files, "Cleaning up...")

    logging.info("Import complete.")
    if progress_callback: progress_callback(100, "Import Complete.")
    
    # --- 6. OPEN FOLDER (NEW) ---
    if new_folder_path:
        open_path_in_explorer(new_folder_path)
        
    return "COMPLETE"

