def get_app_support_dir():
    """
    Finds the cross-platform application support directory.
    Creates it if it doesn't exist.
    """
    if os.name == 'nt': # Windows
        app_dir = os.path.join(os.environ['APPDATA'], 'SD_Importer')
    else: # macOS / Linux
        app_dir = os.path.join(os.path.expanduser('~'), 'Library', 'Application Support', 'SD_Importer')
    
    if not os.path.exists(app_dir):
        os.makedirs(app_dir)
    return app_dir

def get_config_path():
    """Gets the full path to the config.json file."""
    return os.path.join(get_app_support_dir(), 'config.json')

def load_config():
    """
    Loads the target and destination history lists from config.json.
    Returns two empty lists if the file doesn't exist or is corrupt.
    """
    config_file = get_config_path()
    if not os.path.exists(config_file):
        return [], []
        
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
            targets = config.get('target_history', [])
            dests = config.get('destination_history', [])
            return targets, dests
    except json.JSONDecodeError:
        print(f"Error reading config file at {config_file}. Starting fresh.")
        return [], [] # Return empty lists on corruption
    except Exception as e:
        print(f"Failed to load config: {e}")
        return [], []

def save_history(target_list, destination_list):
    """
    Saves the two history lists to the config.json file.
    """
    config_file = get_config_path()
    config = {
        'target_history': target_list,
        'destination_history': destination_list
    }
    try:
        with open(config_file, 'w') as f:
            json.dump(config, f, indent=4)
    except Exception as e:
        print(f"Error saving config: {e}")

def add_to_history(target_path, dest_path):
    """
    Safely adds a new target and destination to the top of the history.
    Removes duplicates if they exist.
    """
    # Sanitize paths first: strip whitespace and DOUBLE quotes
    target_path = target_path.strip().strip('"')
    dest_path = dest_path.strip().strip('"')

    if not target_path or not dest_path:
        print("Skipping history save for empty paths.")
        return

    targets, dests = load_config()

    # Process target history
    if target_path in targets:
        targets.remove(target_path)
    targets.insert(0, target_path)
    
    # Process destination history
    if dest_path in dests:
        dests.remove(dest_path)
    dests.insert(0, dest_path)
    
    # Save the updated lists
    save_history(targets, dests)

def find_source_drives():
    """
    Finds drives that look like SD cards by checking for a 'DCIM' folder.
    """
    print("Scanning for source drives...")
    potential_drives = []
    if os.name == 'nt': # Windows
        from ctypes import windll
        bitmask = windll.kernel32.GetLogicalDrives()
        for i in range(26):
            if (bitmask >> i) & 1:
                drive_letter = f"{chr(65 + i)}:\\"
                potential_drives.append(drive_letter)
    else: # macOS
        mac_volumes = "/Volumes"
        if os.path.exists(mac_volumes):
            potential_drives = [os.path.join(mac_volumes, d) for d in os.listdir(mac_volumes)]
            
    source_drives = []
    for drive in potential_drives:
        dcim_path = os.path.join(drive, 'DCIM')
        if os.path.exists(dcim_path):
            print(f"  Found SD Card: {drive}")
            source_drives.append(os.path.normpath(drive))
            
    return source_drives

# ==============================================================================
#  --- BEGIN HUD ---
# ==============================================================================

class SDImporterApp:
    
    def __init__(self, root):
        # --- FIX #1: The Windows Identity Fix ---
        # This separates your app from generic "Python" on the taskbar
        if sys.platform == "win32":
            try:
                # Arbitrary string, but must be unique
                myappid = 'mattkaaihue.sdimporter.v1.0' 
                ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(myappid)
            except Exception as e:
                print(f"Could not set AppID: {e}")

        self.root = root
        self.root.title("SD Card Importer")
        self.root.geometry("1000x700") 
        self.root.minsize(1000, 700)
        
        # --- State Machine & Threading ---
        self.state = "INITIALIZING"
        self.import_thread = None
        self.pause_event = threading.Event()
        self.countdown_timer = None

        # --- 1. Define and load icons ---
        self._define_icon_placeholders()
        self._load_icons()

        # --- NEW: Set Window Title Bar Icon (In-Memory) ---
        # We use .after(200) to wait for the Windows Window Manager to be ready.
        # This fixes the "Blank Icon" bug on Windows.
        self.root.after(200, self._setup_window_icon)

        # --- NEW: Steal Focus (The "Topmost Toggle") ---
        # We wait 300ms (just after the icon) to snap the window to the front.
        self.root.after(300, self._force_focus)

        # --- 2. Configure Root Grid (4 ROWS) ---
        self.root.columnconfigure(0, weight=1)
        self.root.rowconfigure(0, weight=0) # Top Frame (Icons)
        self.root.rowconfigure(1, weight=0) # Middle Frame (Comboboxes)
        self.root.rowconfigure(2, weight=1) # Spacer Frame (Stretches)
        self.root.rowconfigure(3, weight=0) # Bottom Frame (Controls)

        # --- 3. Create Frames for the 4-Row layout ---
        top_frame = ttk.Frame(self.root)
        top_frame.grid(row=0, column=0, sticky="nsew")
        top_frame.columnconfigure(0, weight=1)
        top_frame.columnconfigure(1, weight=0)
        top_frame.columnconfigure(2, weight=1)

        middle_frame = ttk.Frame(self.root, padding=(0, 10, 0, 20))
        middle_frame.grid(row=1, column=0, sticky="nsew")
        middle_frame.columnconfigure(0, weight=1)
        middle_frame.columnconfigure(1, weight=0) 
        middle_frame.columnconfigure(2, weight=1)

        spacer_frame = ttk.Frame(self.root)
        spacer_frame.grid(row=2, column=0, sticky="nsew")

        self.create_bottom_frame(self.root) 

        # --- 4. Populate Frames ---
        self.create_left_widgets(top_frame, middle_frame)
        self.create_middle_widgets(top_frame)
        self.create_right_widgets(top_frame, middle_frame)

        # --- 5. Connect Logic ---
        self.connect_buttons()
        self.load_history()
        self.set_state("WAITING")
        self.root.after(1000, self.heartbeat) # Start the main app loop after 1 sec

    # ==========================================================================
    #  --- Icon Loading ---
    # ==========================================================================

    def _define_icon_placeholders(self):
        # NEW: Only PNG needed now. ICO variable removed.
        self.app_icon_large_b64 = ""
        self.app_icon_small_b64 = ""

        self.camera_icon_b64 = ""
        self.drive_icon_b64 = ""
        self.arrow_icon_b64 = ""
        self.browse_icon_b64 = ""
        self.remove_icon_b64 = ""

    def _create_icon(self, b64_string):
        if not b64_string or b64_string.startswith("PLACEHOLDER"): return None 
        try:
            image_data = base64.b64decode(b64_string)
            return tk.PhotoImage(data=image_data)
        except Exception as e:
            print(f"ICON LOAD FAILED: {e}")
            return None

    def _load_icons(self):
        # Loads UI icons only. App icon handled in _setup_window_icon
        self.icon_camera = self._create_icon(self.camera_icon_b64)
        self.icon_drive = self._create_icon(self.drive_icon_b64)
        self.icon_arrow = self._create_icon(self.arrow_icon_b64)
        self.icon_browse = self._create_icon(self.browse_icon_b64)
        self.icon_remove = self._create_icon(self.remove_icon_b64)

    def _setup_window_icon(self):
        """
        Sets the window titlebar and taskbar icon directly from memory.
        Works on Windows and Mac/Linux without creating temp files.
        """
        try:
            # Check if we have the PNG data
            if not self.app_icon_large_b64.startswith("PLACEHOLDER"):
                
                # 1. Decode and Create Large Icon
                large_data = base64.b64decode(self.app_icon_large_b64)
                self.icon_img_large = tk.PhotoImage(data=large_data)
                
                # 2. Decode and Create Small Icon (If available)
                # If you haven't pasted the string yet, we fallback to subsampling the large one
                if not self.app_icon_small_b64.startswith("PLACEHOLDER"):
                    small_data = base64.b64decode(self.app_icon_small_b64)
                    self.icon_img_small = tk.PhotoImage(data=small_data)
                else:
                    # Fallback: If no dedicated small icon, shrink the large one
                    # Assuming 256x256 -> subsample(16) -> 16x16
                    self.icon_img_small = self.icon_img_large.subsample(16, 16)
                
                # 3. Apply BOTH icons
                # Tkinter allows passing an arbitrary number of images to iconphoto.
                # The OS selects the best fit for the context.
                self.root.iconphoto(True, self.icon_img_large, self.icon_img_small)
                
                logging.info("App icon applied successfully from memory.")
                
        except Exception as e:
            # If it fails, the app still runs, just with the default feather icon
            logging.error(f"Failed to set app icon: {e}")

    def _force_focus(self):
        """
        Aggressively steals focus on both Windows and Mac.
        Uses the 'Topmost Toggle' trick to bypass OS focus restrictions.
        """
        try:
            # 1. Bring to front of the internal stack
            self.root.lift()
            
            # 2. Force focus (Tkinter's attempt)
            self.root.focus_force()
            
            # 3. The "Nuclear Option" (Cross-Platform)
            # Temporarily set 'Always On Top' to force the window visible
            self.root.attributes("-topmost", True)
            
            # 4. Release 'Always On Top' immediately after the UI refreshes
            # We use after_idle to ensure the 'True' state was registered by the OS first
            self.root.after_idle(self.root.attributes, "-topmost", False)
            
            # 5. One last focus grab for good measure
            self.root.focus_set()
            
            logging.info("Global focus captured.")
            
        except Exception as e:
            logging.warning(f"Focus steal failed: {e}")

    # ==========================================================================
    #  --- Widget Creation ---
    # ==========================================================================

    def create_left_widgets(self, icon_parent, combo_parent):
        left_label_frame = ttk.Frame(icon_parent, padding=(20, 20, 20, 0))
        left_label_frame.grid(row=0, column=0, sticky="nsew")
        left_label_frame.columnconfigure(0, weight=1)
        label_text, label_compound = ("Target", "top") if self.icon_camera else ("Target (SD Card)", "none")
        ttk.Label(left_label_frame, text=label_text, image=self.icon_camera, compound=label_compound, anchor="center", font=("TkDefaultFont", 16, "bold")).grid(row=0, column=0, sticky="ew", pady=(10, 0))
        
        left_combo_frame = ttk.Frame(combo_parent, padding=(20, 0, 20, 0))
        left_combo_frame.grid(row=0, column=0, sticky="nsew")
        left_combo_frame.columnconfigure(0, weight=1)
        self.target_combobox = ttk.Combobox(left_combo_frame, values=[], font=("TkDefaultFont", 12))
        self.target_combobox.grid(row=0, column=0, sticky="ew", pady=5, padx=(0, 5))
        browse_kwargs = {"image": self.icon_browse, "bootstyle": "outline-secondary"} if self.icon_browse else {"text": "Browse...", "bootstyle": "outline-secondary"}
        self.target_browse_btn = ttk.Button(left_combo_frame, **browse_kwargs)
        self.target_browse_btn.grid(row=0, column=1, sticky="w", pady=5, padx=5)
        remove_kwargs = {"image": self.icon_remove, "bootstyle": "outline-danger"} if self.icon_remove else {"text": "X", "bootstyle": "outline-danger"}
        self.target_remove_btn = ttk.Button(left_combo_frame, **remove_kwargs)
        self.target_remove_btn.grid(row=0, column=2, sticky="w", pady=5, padx=5)

    def create_middle_widgets(self, icon_parent):
        middle_frame = ttk.Frame(icon_parent, padding=5)
        middle_frame.grid(row=0, column=1, sticky="n", pady=(10, 0)) 
        arrow_kwargs = {"image": self.icon_arrow} if self.icon_arrow else {"text": "===>", "font": ("TkDefaultFont", 24, "bold")}
        ttk.Label(middle_frame, anchor="center", **arrow_kwargs).grid(row=0, column=0, padx=10)

    def create_right_widgets(self, icon_parent, combo_parent):
        right_label_frame = ttk.Frame(icon_parent, padding=(20, 20, 20, 0))
        right_label_frame.grid(row=0, column=2, sticky="nsew")
        right_label_frame.columnconfigure(0, weight=1)
        label_text, label_compound = ("Destination", "top") if self.icon_drive else ("Destination (Hard Drive)", "none")
        ttk.Label(right_label_frame, text=label_text, image=self.icon_drive, compound=label_compound, anchor="center", font=("TkDefaultFont", 16, "bold")).grid(row=0, column=0, sticky="ew", pady=(10, 0))

        right_combo_frame = ttk.Frame(combo_parent, padding=(20, 0, 20, 0))
        right_combo_frame.grid(row=0, column=2, sticky="nsew")
        right_combo_frame.columnconfigure(0, weight=1)
        self.dest_combobox = ttk.Combobox(right_combo_frame, values=[], font=("TkDefaultFont", 12))
        self.dest_combobox.grid(row=0, column=0, sticky="ew", pady=5, padx=(0, 5))
        browse_kwargs = {"image": self.icon_browse, "bootstyle": "outline-secondary"} if self.icon_browse else {"text": "Browse...", "bootstyle": "outline-secondary"}
        self.dest_browse_btn = ttk.Button(right_combo_frame, **browse_kwargs)
        self.dest_browse_btn.grid(row=0, column=1, sticky="w", pady=5, padx=5)
        remove_kwargs = {"image": self.icon_remove, "bootstyle": "outline-danger"} if self.icon_remove else {"text": "X", "bootstyle": "outline-danger"}
        self.dest_remove_btn = ttk.Button(right_combo_frame, **remove_kwargs)
        self.dest_remove_btn.grid(row=0, column=2, sticky="w", pady=5, padx=5)
        
    def create_bottom_frame(self, parent):
        ttk.Separator(parent, orient="horizontal", bootstyle="secondary").grid(row=2, column=0, sticky="ew")
        bottom_frame = ttk.Frame(parent, padding=20)
        bottom_frame.grid(row=3, column=0, sticky="ew")
        bottom_frame.columnconfigure(2, weight=1)
        self.move_files_var = tk.BooleanVar(value=True)
        self.move_files_check = ttk.Checkbutton(bottom_frame, text="Move files (Delete from source)", variable=self.move_files_var, bootstyle="round-toggle")
        self.move_files_check.grid(row=0, column=0, sticky="w", padx=(0, 20), pady=10)
        self.run_pause_button = ttk.Button(bottom_frame, text="Initializing...", bootstyle="primary")
        self.run_pause_button.grid(row=0, column=1, sticky="w", padx=(0, 20), pady=10)
        self.status_label = ttk.Label(bottom_frame, text="Initializing...", font=("TkDefaultFont", 10))
        self.status_label.grid(row=0, column=2, sticky="ew", padx=10, pady=10)
        self.progress_bar = ttk.Progressbar(bottom_frame, orient='horizontal', mode='determinate', value=0, bootstyle="primary-striped")
        self.progress_bar.grid(row=1, column=0, columnspan=3, sticky="ew", pady=(10, 0))

    # ==========================================================================
    #  --- STATE MACHINE & LOGIC ---
    # ==========================================================================

    def _sanitize_path(self, path):
        """Helper to strip whitespace and DOUBLE quotes from user input."""
        return path.strip().strip('"')

    def set_state(self, new_state):
        """The central function for controlling the app's UI and behavior."""
        if self.state == new_state and new_state != "COUNTDOWN": 
            return 
        
        self.state = new_state
        print(f"APP STATE -> {new_state}")

        self.root.unbind("<KeyPress>")

        if self.state == "WAITING":
            self.status_label.config(text="Waiting for drives...")
            self.run_pause_button.config(text="Waiting...", state="disabled")
            self.progress_bar.config(value=0, bootstyle="primary-striped")
            self._cancel_countdown() 

        elif self.state == "READY":
            self.status_label.config(text="Drives ready. Starting countdown...")
            self.set_state("COUNTDOWN") 

        elif self.state == "COUNTDOWN":
            self.run_pause_button.config(text="Pause", state="normal")
            self.start_countdown(6) 
            self.root.bind("<KeyPress>", self.on_key_press)

        elif self.state == "IMPORTING":
            self.run_pause_button.config(text="Pause", state="normal")
            self.start_import_thread() 

        elif self.state == "PAUSING":
            self.status_label.config(text="Pausing after current file...")
            self.run_pause_button.config(text="Pausing...", state="disabled")

        elif self.state == "PAUSED":
            self.status_label.config(text="Import Paused.")
            self.run_pause_button.config(text="Run", state="normal")
            self._cancel_countdown()
            
        elif self.state == "FINISHED":
            self.status_label.config(text="Import Finished!")
            self.run_pause_button.config(text="Run Again", state="normal")
            self.progress_bar.config(value=100, bootstyle="success") 

    def heartbeat(self):
        """Runs every 3 seconds to check for drives."""
        if self.state in ["WAITING", "READY", "PAUSED", "FINISHED"]: 
            try:
                current_target = self._sanitize_path(self.target_combobox.get())
                if not current_target or not os.path.exists(current_target):
                    self.auto_detect_drives()
                
                target_path = self._sanitize_path(self.target_combobox.get())
                dest_path = self._sanitize_path(self.dest_combobox.get())

                if os.path.exists(target_path) and os.path.exists(dest_path):
                    if self.state == "WAITING":
                        self.set_state("READY")
                elif self.state not in ["WAITING"]: 
                    self.set_state("WAITING")
            except Exception as e:
                print(f"Heartbeat error: {e}")
                self.set_state("WAITING")
        
        self.root.after(3000, self.heartbeat)

    def start_countdown(self, seconds):
        """Runs the 6-second countdown timer."""
        self._cancel_countdown() 
        
        if seconds > 0:
            self.status_label.config(text=f"Importing in {seconds}...")
            self.countdown_timer = self.root.after(1000, lambda: self.start_countdown(seconds - 1))
        else:
            self.status_label.config(text="Importing...")
            self.set_state("IMPORTING")

    def _cancel_countdown(self):
        if self.countdown_timer:
            self.root.after_cancel(self.countdown_timer)
            self.countdown_timer = None

    def on_run_pause_click(self):
        """Handles all clicks for the main Run/Pause/Run Again button."""
        if self.state in ["COUNTDOWN", "IMPORTING"]:
            self.pause_import()
        elif self.state in ["PAUSED", "FINISHED", "WAITING"]:
            target_path = self._sanitize_path(self.target_combobox.get())
            dest_path = self._sanitize_path(self.dest_combobox.get())
            if os.path.exists(target_path) and os.path.exists(dest_path):
                self.set_state("READY")
            else:
                self.status_label.config(text="Error: Cannot find Source or Destination.")
                self.set_state("WAITING")

    def on_key_press(self, event):
        """Pauses the countdown on any key press."""
        focused_widget = self.root.focus_get()
        if focused_widget is None or not isinstance(focused_widget, ttk.Combobox):
            if self.state == "COUNTDOWN":
                self.pause_import()

    def pause_import(self):
        """Logic to safely pause the import."""
        if self.state == "COUNTDOWN":
            self._cancel_countdown()
            self.set_state("PAUSED")
        
        elif self.state == "IMPORTING":
            self.pause_event.set()
            self.set_state("PAUSING")

    # ==========================================================================
    #  --- Threading & Engine Logic ---
    # ==========================================================================

    def start_import_thread(self):
        """Starts the importer engine in a separate thread."""
        self.pause_event.clear() 
        
        target = self._sanitize_path(self.target_combobox.get())
        dest = self._sanitize_path(self.dest_combobox.get())
        move = self.move_files_var.get()
        
        # Use our imported util function
        add_to_history(target, dest)
        self.load_history() 
        
        self.progress_bar.config(bootstyle="primary-striped")
        
        self.import_thread = threading.Thread(
            target=self.import_worker,
            # Use our imported engine function
            args=(target, dest, move, self.pause_event), 
            daemon=True
        )
        self.import_thread.start()
        
        self.monitor_import_thread()
        
    def import_worker(self, target, dest, move, pause_event):
        """
        The function that runs inside the thread.
        Calls the "Brain" (importer_engine).
        """
        try:
            # Use our imported engine function
            run_import(
                source_dir=target,
                dest_base=dest,
                delete_source=move,
                pause_event=pause_event, 
                progress_callback=self.update_progress
            )
        except Exception as e:
            print(f"--- !!! IMPORT THREAD FAILED !!! ---")
            print(e)
            self.root.after(0, lambda: self.update_progress(0, f"ERROR: {e}"))
            self.root.after(0, lambda: self.set_state("WAITING"))

    def monitor_import_thread(self):
        """Checks if the import thread is still running."""
        if self.import_thread.is_alive():
            self.root.after(100, self.monitor_import_thread)
        else:
            if self.state not in ["PAUSED", "FINISHED", "WAITING"]:
                print("Import thread finished.")
                if self.pause_event.is_set():
                    self.set_state("PAUSED")
                else:
                    self.set_state("FINISHED")

    def update_progress(self, percent, status):
        """
        A thread-safe callback for the engine to update the UI.
        """
        def _safe_update():
            self.progress_bar.config(value=percent)
            self.status_label.config(text=status)
            
            if status == "Import Complete.":
                self.set_state("FINISHED")
            elif status == "Pausing...":
                self.set_state("PAUSED")
        
        self.root.after(0, _safe_update)

    # ==========================================================================
    #  --- Button & Utility Logic ---
    # ==========================================================================

    def connect_buttons(self):
        """Connects all the browse/remove buttons to their functions."""
        self.target_browse_btn.config(command=self.browse_target)
        self.dest_browse_btn.config(command=self.browse_destination)
        self.target_remove_btn.config(command=self.remove_target_history)
        self.dest_remove_btn.config(command=self.remove_dest_history)
        self.run_pause_button.config(command=self.on_run_pause_click)
        self.root.bind("<KeyPress>", self.on_key_press)
        
    def load_history(self):
        """Loads path history from config file into comboboxes."""
        # Use our imported util function
        targets, dests = load_config()
        
        self.target_combobox.config(values=[(t,) for t in targets])
        self.dest_combobox.config(values=[(d,) for d in dests])
        
        if targets: self.target_combobox.set(targets[0])
        if dests: self.dest_combobox.set(dests[0])

    def browse_target(self):
        path = filedialog.askdirectory(title="Select Source Drive (SD Card)")
        if path:
            self.target_combobox.set(os.path.normpath(path))
            
    def browse_destination(self):
        path = filedialog.askdirectory(title="Select Destination Folder")
        if path:
            self.dest_combobox.set(os.path.normpath(path))
            
    def remove_target_history(self):
        path_to_remove = self._sanitize_path(self.target_combobox.get())
        if not path_to_remove: return
        
        targets, dests = load_config()
        if path_to_remove in targets:
            targets.remove(path_to_remove)
            save_history(targets, dests) # Use util function
            self.load_history() 
            self.target_combobox.set("") 
            
    def remove_dest_history(self):
        path_to_remove = self._sanitize_path(self.dest_combobox.get())
        if not path_to_remove: return
        
        targets, dests = load_config()
        if path_to_remove in dests:
            dests.remove(path_to_remove)
            save_history(targets, dests) # Use util function
            self.load_history() 
            self.dest_combobox.set("") 

    def auto_detect_drives(self):
        """Called by heartbeat to find drives."""
        current_target = self._sanitize_path(self.target_combobox.get())
        if current_target and os.path.exists(current_target):
            return 
        try:
            drives = find_source_drives() # Use util function
            if drives:
                self.target_combobox.set(drives[0])
        except Exception as e:
            print(f"Auto-detect error: {e}")

